// Arte del personaje embebido (base64) — evita depender de recursos del
// bundle/asset catalog, que fallan en device con provisioning gratis.
import UIKit

enum WidgetArt {
    static func image(_ name: String) -> UIImage? {
        guard let b64 = data[name], let d = Data(base64Encoded: b64) else { return nil }
        return UIImage(data: d)
    }

    private static let data: [String: String] = [
        "WidgetVoz": "",
        "WidgetChat": "",
        "WidgetRegistrar": "",
    ]
}
